package dev.maboullaite.fhemni.memberanalysis;

import java.time.*;
import java.util.*;
import java.sql.*;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;
import dev.maboullaite.fhemni.gemini.VideoIntelligenceGateway;
import dev.maboullaite.fhemni.model.*;
import tools.jackson.databind.ObjectMapper;

@Repository
public class MemberAnalysisRepository {
    private final JdbcClient jdbc;private final ObjectMapper mapper;private final MemberAllowanceRepository allowances;
    public MemberAnalysisRepository(JdbcClient jdbc,ObjectMapper mapper,MemberAllowanceRepository allowances){this.jdbc=jdbc;this.mapper=mapper;this.allowances=allowances;}
    public void lockOwner(UUID user){jdbc.sql("SELECT id FROM app_users WHERE id=:user FOR UPDATE").param("user",user).query(UUID.class).single();}
    public String role(UUID user){return jdbc.sql("SELECT role FROM app_users WHERE id=:user").param("user",user).query(String.class).single();}
    public long used(UUID user,YearMonth month){return allowances.used(user,"VIDEO",MemberAllowanceWindow.of(month));}
    public void chargeVideo(UUID id,UUID user,int limit){allowances.reserve(id,id,user,"VIDEO",limit,Instant.now());}
    public boolean active(UUID user){return jdbc.sql("SELECT COUNT(*) FROM member_analysis_active WHERE user_id=:user").param("user",user).query(Long.class).single()>0;}
    public Optional<MemberJob> byKey(UUID user,String key){return jdbc.sql("SELECT * FROM member_analysis_jobs WHERE user_id=:user AND idempotency_key=:key").param("user",user).param("key",key).query(this::map).optional().map(job->{if(job.expiresAt()!=null&&!job.expiresAt().isAfter(Instant.now()))throw new NoSuchElementException("Analysis not found.");return job;});}
    public MemberJob owner(UUID id,UUID user){return jdbc.sql("SELECT * FROM member_analysis_jobs WHERE id=:id AND user_id=:user AND (expires_at IS NULL OR expires_at>:now)").param("id",id).param("user",user).param("now",Instant.now().atOffset(ZoneOffset.UTC)).query(this::map).optional().orElseThrow(()->new NoSuchElementException("Analysis not found."));}
    public dev.maboullaite.fhemni.government.GovernmentViews.Page<MemberJob> history(UUID user,int page){if(page<1||page>100000)throw new IllegalArgumentException("Invalid page.");var now=Instant.now().atOffset(ZoneOffset.UTC);long count=jdbc.sql("SELECT COUNT(*) FROM member_analysis_jobs WHERE user_id=:user AND (expires_at IS NULL OR expires_at>:now)").param("user",user).param("now",now).query(Long.class).single();var rows=jdbc.sql("SELECT * FROM member_analysis_jobs WHERE user_id=:user AND (expires_at IS NULL OR expires_at>:now) ORDER BY created_at DESC,id LIMIT 10 OFFSET :offset").param("user",user).param("now",now).param("offset",(page-1)*10).query(this::map).list().stream().map(job->new MemberJob(job.id(),job.videoUrl(),job.videoId(),job.language(),job.state(),job.createdAt(),job.updatedAt(),null,job.errorCode(),job.title(),job.expiresAt())).toList();return new dev.maboullaite.fhemni.government.GovernmentViews.Page<>(rows,page,10,count);}
    public record Claim(UUID id,UUID userId,UUID leaseToken,UUID usageReservationId,String model,String promptVersion,String factCheckModel,String factCheckPromptVersion,String credentialVersion) {}
    @Transactional public Optional<Claim> claim(Instant now){var ids=jdbc.sql("SELECT id FROM member_analysis_jobs WHERE state='QUEUED' ORDER BY created_at,id LIMIT 1 FOR UPDATE SKIP LOCKED").query(UUID.class).list();if(ids.isEmpty())return Optional.empty();var id=ids.getFirst();var token=UUID.randomUUID();jdbc.sql("UPDATE member_analysis_jobs SET state='PROCESSING',lease_token=:token,lease_until=:until,updated_at=:now WHERE id=:id").param("id",id).param("token",token).param("until",now.plus(Duration.ofHours(1)).atOffset(ZoneOffset.UTC)).param("now",now.atOffset(ZoneOffset.UTC)).update();return jdbc.sql("SELECT id,user_id,lease_token,usage_reservation_id,model,prompt_version,fact_check_model,fact_check_prompt_version,credential_version FROM member_analysis_jobs WHERE id=:id").param("id",id).query(Claim.class).optional();}
    public boolean leaseValid(Claim claim){return jdbc.sql("SELECT COUNT(*) FROM member_analysis_jobs WHERE id=:id AND lease_token=:token AND state='PROCESSING' AND lease_until>:now").param("id",claim.id()).param("token",claim.leaseToken()).param("now",Instant.now().atOffset(ZoneOffset.UTC)).query(Long.class).single()==1;}
    @Transactional public void finish(Claim claim,VideoReport report,String interaction,String error){lockOwner(claim.userId());var now=Instant.now();int changed=jdbc.sql("UPDATE member_analysis_jobs SET state=:state,report_json=:report,provider_interaction_id=:interaction,error_code=:error,allowance_charged=:charged,updated_at=:now,expires_at=:expires WHERE id=:id AND state='PROCESSING' AND lease_token=:token AND lease_until>:now").param("id",claim.id()).param("token",claim.leaseToken()).param("state",report==null?"FAILED":"READY").param("report",report==null?null:mapper.writeValueAsString(report),Types.LONGVARCHAR).param("interaction",interaction,Types.LONGVARCHAR).param("error",error,Types.VARCHAR).param("charged",report!=null).param("now",now.atOffset(ZoneOffset.UTC)).param("expires",now.plus(Duration.ofDays(30)).atOffset(ZoneOffset.UTC)).update();if(changed==1){jdbc.sql("DELETE FROM member_analysis_active WHERE job_id=:id").param("id",claim.id()).update();if(report==null)allowances.refundVideo(claim.id());}}
    @Transactional public void expire(Instant now){jdbc.sql("UPDATE member_analysis_jobs SET state='FAILED',allowance_charged=FALSE,error_code='PROCESSING_INTERRUPTED',updated_at=:now,expires_at=:expires WHERE state='PROCESSING' AND lease_until<:now").param("now",now.atOffset(ZoneOffset.UTC)).param("expires",now.plus(Duration.ofDays(30)).atOffset(ZoneOffset.UTC)).update();jdbc.sql("UPDATE member_allowance_receipts SET charged=FALSE WHERE kind='VIDEO' AND job_id IN (SELECT id FROM member_analysis_jobs WHERE allowance_charged=FALSE)").update();jdbc.sql("DELETE FROM member_analysis_active WHERE job_id IN (SELECT id FROM member_analysis_jobs WHERE state IN ('READY','FAILED'))").update();}
    public Optional<Claim> identity(UUID id){return jdbc.sql("SELECT id,user_id,lease_token,usage_reservation_id,model,prompt_version,fact_check_model,fact_check_prompt_version,credential_version FROM member_analysis_jobs WHERE id=:id").param("id",id).query(Claim.class).optional();}
    public String interaction(UUID id){return jdbc.sql("SELECT provider_interaction_id FROM member_analysis_jobs WHERE id=:id").param("id",id).query(String.class).optional().orElse(null);}
    public MemberJob create(UUID id,UUID user,String key,String url,String video,OutputLanguage language,long seconds,UUID reservation,VideoIntelligenceGateway gateway){var now=Instant.now().atOffset(ZoneOffset.UTC);jdbc.sql("INSERT INTO member_analysis_jobs(id,user_id,idempotency_key,video_url,video_id,language,state,allowance_month,duration_seconds,usage_reservation_id,model,prompt_version,fact_check_model,fact_check_prompt_version,credential_version,created_at,updated_at) VALUES(:id,:user,:key,:url,:video,:language,'QUEUED',:month,:seconds,:reservation,:model,:prompt,:facts,:factsPrompt,:credential,:now,:now)").param("id",id).param("user",user).param("key",key).param("url",url).param("video",video).param("language",language.name()).param("month",YearMonth.now(ZoneOffset.UTC).atDay(1)).param("seconds",seconds).param("reservation",reservation).param("model",gateway.model()).param("prompt",gateway.promptVersion()).param("facts",gateway.factCheckModel()).param("factsPrompt",gateway.factCheckPromptVersion()).param("credential",gateway.credentialVersion()).param("now",now).update();jdbc.sql("INSERT INTO member_analysis_active(user_id,job_id) VALUES(:user,:id)").param("user",user).param("id",id).update();return owner(id,user);}
    @Transactional public void failQueued(UUID id,UUID user){lockOwner(user);var now=Instant.now();int changed=jdbc.sql("UPDATE member_analysis_jobs SET state='FAILED',allowance_charged=FALSE,error_code='PROCESSING_FAILED',updated_at=:now,expires_at=:expires WHERE id=:id AND user_id=:user AND state='QUEUED'").param("id",id).param("user",user).param("now",now.atOffset(ZoneOffset.UTC)).param("expires",now.plus(Duration.ofDays(30)).atOffset(ZoneOffset.UTC)).update();if(changed==1){jdbc.sql("DELETE FROM member_analysis_active WHERE job_id=:id").param("id",id).update();allowances.refundVideo(id);}}
    private MemberJob map(ResultSet row,int ignored)throws SQLException{String json=row.getString("report_json");VideoReport report=json==null?null:mapper.readValue(json,VideoReport.class);var expires=row.getObject("expires_at",OffsetDateTime.class);return new MemberJob(row.getObject("id",UUID.class),row.getString("video_url"),row.getString("video_id"),OutputLanguage.valueOf(row.getString("language")).code(),row.getString("state"),row.getObject("created_at",OffsetDateTime.class).toInstant(),row.getObject("updated_at",OffsetDateTime.class).toInstant(),report,row.getString("error_code"),report==null?null:report.title(),expires==null?null:expires.toInstant());}
}
